css:
.fme-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.fme-root,.fme-root *,.fme-root *::before,.fme-root *::after{box-sizing:border-box}
.fme-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.fme-root img{display:block;border:0;max-width:none}
.fme-root > [data-node-id]{will-change:transform}
.fme-root [hidden]{display:none!important}
.fme-root [data-sh-theme="dark"]{display:none!important}
.fme-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.fme-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.fme-root .fme_n2205_255{align-content:stretch;display:flex;gap:5px;align-items:center;position:relative;flex-shrink:0;width:187px}
.fme-root .fme_nI2205_255_2205_187{height:12.515px;position:relative;flex-shrink:0;width:11.515px}
.fme-root .fme_x2{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.fme-root .fme_nI2205_255_2205_189{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:17px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #464d5c);font-size:14px;white-space:nowrap;width:140px}
.fme-root [data-name="Symbol/SPST (Horizontal) Wrap"] > * > [data-name="Glyph"] > [data-name="Glyph"]{transform-origin:0 0;transform:translate(0,15px) rotate(-90deg)}
.fme-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.fme-root > [data-node-id="2143:549"]{width:1310px;height:460px}
.fme-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.fme-root[data-theme="dark"] [data-name="Button/Ack (Hover)"] p{color:var(--wa-text, #0e1a2c)!important}
.fme-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="logo chip"] img{filter:brightness(0) invert(1)!important}
.fme-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="WEMB Studio"]{color:var(--wa-text, #fff)!important}
.fme-root[data-theme="dark"] :is([data-name="Side Panel (Left)"],[data-name="Side Panel (Right)"]) > [data-name="Panel Body"]{box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),0 10px 30px rgba(0,0,0,.45)!important}
.fme-root[data-theme="dark"] :is([data-name="Widget/Weather"] > [data-name="Row"],[data-name="Widget/Alarm Event"] > [data-name="Button Group"],[data-name="Widget/Mini Map"] > [data-name="Body"],[data-name="Widget/Plant Generation"] > [data-name="Body"],[data-name="Widget/Weekly Solar Generation"] > [data-name="Body"]){background:var(--wa-surface, #1f252e)!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),inset 0 1px 0 rgba(255,255,255,.05),0 6px 16px rgba(0,0,0,.35)!important}
.fme-root[data-theme="dark"] :is([data-name="Widget/Alarm Event"],[data-name="Widget/Mini Map"]) > [data-name="Header"],.fme-root[data-theme="dark"] :is([data-name="Widget/Plant Generation"],[data-name="Widget/Weekly Solar Generation"]) > [data-name="Body"] > [data-name="Header"]{background:linear-gradient(to top,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf))!important;box-shadow:0 4px 12px rgba(31,95,207,.35),inset 0 1px 0 rgba(255,255,255,.18)!important}
.fme-root[data-theme="dark"] :is([data-name="Button/Solar"],[data-name="Button/Power Equipment"]) > [data-name="Body"] > [data-name="Background"]{background:linear-gradient(to right,color-mix(in srgb, var(--wa-point, rgb(59 130 234)) 55%, transparent) 28%,var(--wa-point, #2466d6) 62%)!important}
.fme-root[data-theme="dark"] [data-name="Key Background"]{background:linear-gradient(to left,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf) 53%)!important}
.fme-root[data-theme="dark"] [data-name^="Item/"] [data-name="Value"]{color:var(--wa-text, #f1f3f8)!important}
.fme-root[data-theme="dark"] [data-name^="Direction/"] p,.fme-root[data-theme="dark"] p[data-name^="Direction/"]{color:var(--wa-point, #1d2747)!important}
.fme-root[data-theme="dark"] [data-name^="Meter Card/"] [data-name="Title"]{color:var(--wa-text, #0f1420)!important;font-weight:600}
.fme-root[data-theme="dark"] [data-name="Badge/Critical"] p{color:var(--wa-danger, #ff5a57)!important}
.fme-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"]){background:var(--wa-surface, #232a35)!important}
.fme-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"])::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 12%, transparent)!important}
.fme-root[data-theme="dark"] .fme_nI2205_255_2205_189{color:var(--wa-text-sub, #bfc2c6)}
